  { intros a. apply Hfr. unfold PbrvY124.F0.
    apply L5K.outside_nil_e. }
  split. exact FRW.
  split. { intros i Hi. apply FRW; rewrite ?BG.unsigned_lit by exact Hi; assumption. }
  apply L5K.nth_error_single in Hnth. subst ps.
  change (SR.ps_pc PbrvY124.ps0) with 0xafda8 in Hms. change (SR.ps_regs PbrvY124.ps0) with (map (fun i => (i, nth i PbrvY124.regs_out0 (ELit 0))) (seq 1 31)) in Hregs.
  change (SR.ps_cells PbrvY124.ps0) with PbrvY124.cells0 in Hcells.
  split. { exact Hms. }
  split. { intros j Hj. apply (BG.kept_regs E E' R R' PbrvY124.regs0 PbrvY124.regs_out0 72 KS_brvY124 KS_brvY124_ok HR Hag Hregs j Hj). }
  split. { rewrite (BG.out_reg PbrvY124.regs_out0 E' R' 1 Hregs) by (clear; lia). cbn [nth PbrvY124.regs_out0]. first [reflexivity | wordP' ZA Hag]. }
  split. { rewrite (BG.out_reg PbrvY124.regs_out0 E' R' 10 Hregs) by (clear; lia). cbn [nth PbrvY124.regs_out0]. first [reflexivity | wordP' ZA Hag]. }
  rewrite (BG.out_reg PbrvY124.regs_out0 E' R' 11 Hregs) by (clear; lia). cbn [nth PbrvY124.regs_out0]. first [reflexivity | wordP' ZA Hag].
Qed.

End PEBRVP2.
